presetParts.presetInit:
i=0; loop (5000,i[0]=0; gmem[i]=0; i+=1;);
octaves=3; minbpm=75; maxbpm=200; nres_oct=60; 
nres_extra=nres_oct/log(2)*log(maxbpm/minbpm/2);
nres=nres_oct*octaves+nres_extra;
bstep = log(2)/nres_oct;
nres_out = ceil(nres_oct+nres_extra); //int is necessary !

maxind = 40;
i=0;
loop (nres,
 //precalculate BPM
  (8*i)[3]=minbpm*exp(i*bstep); 
 //precalculate weighting
  if (i<=nres_out,(8*i)[4]=min(2,1+sin($pi*i/nres_out)*3)/2,0);; 
i+=1); 

tmov = 1333; start = 0.0; speed=0.1;

presetParts.perFrame:
//Martin/Nitorami - DFT based BPM identification
dec_m=exp(-2*dt);
vol=2*bass_att+mid_att+treb_att;
vol_ = vol_*dec_m + vol*(1-dec_m);

dt=1/fps; 
tcorr = (dt - dt_);
dt_= dt;
treal += dt + tcorr*38;
exc=vol;
d0= exp(-1.5*dt);
i=0; avg = 0;
loop (nres,
  n = 8*i;
  w = 2*$pi/60*n[3];
  d = 1-dt*w*0.013; 
  arg = treal*w + tcorr*15000;
  n[1] = n[1]*d +exc*cos(arg)*(1-d); 
  n[2] = n[2]*d +exc*sin(arg)*(1-d); 
  if (i<nres_out, 
    n2 = 8*(i+nres_oct);
    n4 = 8*(i+nres_oct*2);
    sum = sqrt (sqr(n[1])+sqr(n[2]) + sqr(n2[1])+sqr(n2[2]) + sqr(n4[1])+sqr(n4[2]));
    avg += sum;
    n[0]= n[0]*d0+sum*(1-d0)*n[4];
    if (n[0]>(8*promax)[0], promax=max(2,min(nres_out-2,i));,0); 
  ,0);
i += 1;);
avg_ = avg_*d0 + (1-d0)*avg/nres_out;

m8 = 8*maxind;
wait += abs(m8[0]-(8*promax)[0])*dt*100; 
if (wait>abs(promax-maxind)*80/nres_oct, maxind=promax; wait = 0,0);

//OUTPUT
BPM  = m8[3]; // BPM in nres_out discrete steps
BPMtime += BPM/60*dt*4;
d=exp(-2*dt);
quali= quali*d + (1-d)*min (3,max(0,m8[0]*2.2));

speed = speed*d + (1-d)*BPM*.00045;
trel1 += bass*dt;
rott  = $pi*0.17* atan(8*sin(time*.031+trel1*0.005)) * (1+0.6*sin(BPMTime*0.02));
q1 = cos(rott);
q2 = sin(rott);
q3 = -q2;
q4 = q1;
tmov += speed*dt;
q6 = tmov;
q7=speed*500;
zoom_ = 2.5;
q8 = zoom_;

q10=BPMtime;
q11 =  0.007*max(0,sqrt(mid_att+.5))*max(0,quali-0.3)*
             min(1,max(0,1+sin(BPMTime*$pi/15)));
q13 = sin((time+BPMTime)/60)/3 + 0.55;

reg32 = aspecty;
q15=start;
start *= exp(-8*dt);;
monitor = quali;

presetParts.warp:
shader_body {
uv = uv_orig;
float2 hor = float2(1,0)*texsize.zw*.7;
float2 ver = float2(0,1)*texsize.zw*.7;;

uv += (tex2D(sampler_noise_lq,uv*4+rand_frame)-0.5)*0.00;
float dx = tex2D(sampler_main,uv+hor).r - tex2D(sampler_main,uv-hor).r;
float dy = tex2D(sampler_main,uv+ver).r - tex2D(sampler_main,uv-ver).r;
float2 dz = float2 (dx,dy);


float3 blur = GetBlur1(frac(uv));


double3 crisp = tex2D(sampler_main,uv+dz*.002);
crisp += - length(dz)*.01-0.014*blur;

ret.r = max (0.3,crisp).r;
ret.b = GetPixel(uv*1.2).b*0.8;
ret.g = GetPixel(uv*2).b*22;

}

presetParts.comp:
/*
  Martin's milkdrop edit of XorDev's "Starship" on shadertoy.com
  Inspired by the debris from SpaceX's 7th Starship test:
  https://x.com/elonmusk/status/1880040599761596689
  Original twigl version:
  https://x.com/XorDev/status/1880344887033569682
*/

#define sat saturate
static const float zoom = 1.5*q8*aspect.y, T = q6,speed=q7,  trails = 32, 
                   BPMtime=q10, vb=q11, zz=q13;

shader_body{
  float2 uv1 = (uv_orig-0.5)*aspect.xy + 0.02*float2(sin(time*0.51),sin(time*0.19));
  float2 p, q = mul (uv1, float2x2(_qa))/zoom;
  float3 S = 0, C = float3(12, 2, 3), col, scr;

  for (int i = 0; i < trails; i++)
  {
    float j=i/trails; 
    p = q* (1-zz*j)+ 0.053* sin (pow(i+1.,float2(17,23)/51)*T)*float2(2,1.5);

    col =  (cos(C*cos(i)) +bass_att);
    float2 uvt = p + float2((j-.5)/8*0,T*(1+frac(i*M_PI)));  
    scr = GetPixel(3.25*frac(uvt.yx/aspect.xy+.5));
    float trail = 1 / length (max(p, p / float2(2, scr.r * speed)));
    S += (trail*scr.g*(-p.y))*0.3*(i%2);
    S += trail *   0.0015 * col ;
    S += vb/length(p)* (sat(1-pow((BPMtime)%trails-i,2)) +
                       sat(1-pow((BPMtime*2)%trails-i,2))*2*col);
 }
 ret = 1-exp(-(sat(q.x)*float3(0,0.6,1)*2  + pow(S,1.8)/trails));
//MilkDrop3 Color Mode:
//ret /= float3(-0.4,1.1,2.8);
}
